using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Mail.Domain;
public sealed class MailAlias:ITenantEntity{private MailAlias(){} public MailAlias(Guid municipalityId,string address,string targetAddress){Id=Guid.NewGuid();MunicipalityId=municipalityId;Address=address.Trim().ToLowerInvariant();TargetAddress=targetAddress.Trim().ToLowerInvariant();IsActive=true;CreatedAt=DateTimeOffset.UtcNow;}public Guid Id{get;private set;}public Guid MunicipalityId{get;private set;}public string Address{get;private set;}=string.Empty;public string TargetAddress{get;private set;}=string.Empty;public bool IsActive{get;private set;}public DateTimeOffset CreatedAt{get;private set;}public void Deactivate()=>IsActive=false;}
